// A adapter une seule fois : ID du document Grist + webhook Discord.
const docId = 'cRP1WgZQv7KmwmVrUbuEF8';
const discordWebhookUrl = 'https://discord.com/api/webhooks/1551618475179511940/BsIPFGMDe0jiylrnEGTluRaPCP3zEi2tEWangoaZHgT_uShe2Zyy4dgTIRkLRjQ1cxZW';
const body = $input.first().json.body || {};
return [{
  json: {
    docId,
    discordWebhookUrl,
    userId: Number(body.userId),
    // Un ou plusieurs BatchId (session x1/x5/x10, voir opening.js) : jamais
    // les infos carte elles-memes, revalidees ici depuis Grist pour qu'un
    // client ne puisse pas fabriquer une fausse annonce/partage.
    batchIds: Array.isArray(body.batchIds) ? body.batchIds.map(String) : (body.batchIds != null ? [String(body.batchIds)] : []),
    action: (body.action || 'auto').toString(),
    imageBase64: (body.imageBase64 || '').toString()
  }
}];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
function firstAttachment(v) {
  if (!Array.isArray(v) || !v.length) return null;
  const ids = v[0] === 'L' ? v.slice(1) : v;
  return ids.length ? ids[0] : null;
}
const cfg = $('Set Config').first().json;
const users = $('Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const cards = $('Get Cards').all().map((i) => i.json).filter((r) => r.id != null);
const rarities = $('Get Rarities').all().map((i) => i.json).filter((r) => r.id != null);
const pulls = $('Get Pulls').all().map((i) => i.json).filter((r) => r.id != null);

const user = users.find((u) => u.id === cfg.userId);
const pseudo = (user && user.Pseudo) || 'Un joueur';
const mention = user && user.DiscordId ? `<@${user.DiscordId}>` : `**${pseudo}**`;

const cardById = {}; cards.forEach((c) => { cardById[c.id] = c; });
const rarityById = {}; rarities.forEach((r) => { rarityById[r.id] = r; });
const imageBase = 'https://n8n.matiboux.com/webhook/image';
function hexToInt(hex) { return parseInt((hex || '9aa0b4').replace('#', ''), 16) || 0x9aa0b4; }
function imageOf(card) { const id = firstAttachment(card.Image); return id ? { url: `${imageBase}?id=${id}` } : undefined; }

// Les pulls de CETTE session (un ou plusieurs boosters ouverts d'affilee) :
// identifies par User + BatchId in cfg.batchIds - jamais par des donnees
// carte envoyees par le client (voir Set Config).
const myPulls = pulls.filter((p) => refId(p.User) === cfg.userId && cfg.batchIds.includes(String(p.BatchId)));
const resolved = myPulls
  .map((p) => ({ card: cardById[refId(p.Card)], rarity: null }))
  .map((r) => (r.card ? { card: r.card, rarity: rarityById[refId(r.card.Rarity)] } : r))
  .filter((r) => r.card && r.rarity);

if (!resolved.length) {
  return [{ json: { shouldNotify: false } }];
}

const best = resolved.reduce((a, b) => (b.rarity.SortOrder || 0) > (a.rarity.SortOrder || 0) ? b : a);
const others = resolved.filter((r) => r !== best).map((r) => r.card.Name);

if (cfg.action === 'share') {
  // Partage manuel (bouton "Partager sur Discord") : toujours envoye, quelle
  // que soit la rarete - c'est le joueur qui choisit de montrer son lot.
  // L'image composite (carte principale + reste du lot + branding, generee
  // cote front en canvas - voir opening.js buildShareImage) porte deja tout
  // le detail visuel, donc l'embed texte reste minimal ; elle est jointe en
  // piece jointe Discord (voir node "Send Discord Share") et referencee ici
  // via 'attachment://share.jpg' (JPEG, pas PNG - un PNG sans perte de cette
  // image full de degrades/photos depassait la limite de 1 Mo du serveur et
  // se faisait rejeter en 413, cote client voir opening.js buildShareImage).
  // Repli sur l'image brute de la carte si le canvas a echoue cote client
  // (imageBase64 absent).
  const hasImage = !!cfg.imageBase64;
  return [{ json: {
    shouldNotify: true,
    webhookUrl: cfg.discordWebhookUrl,
    imageBase64: cfg.imageBase64,
    content: `\u{1F4E3} ${mention} partage son ouverture avec nous !`,
    embeds: [{ color: hexToInt(best.rarity.ColorHex), image: hasImage ? { url: 'attachment://share.jpg' } : imageOf(best.card) }]
  } }];
}

// action === 'auto' (ou toute autre valeur) : annonce automatique reservee
// aux tirages notables (Mythique > Legendaire > Epique) - la Mythique et la
// Legendaire pinguent le joueur, l'Epique reste une annonce discrete sans
// ping (trop frequente pour meriter un ping direct). Envoyee par le FRONT
// une fois le reveal termine (jamais au tirage cote backend), pour ne pas
// spoiler le joueur qui n'a pas encore vu sa propre carte.
const byKey = (key) => resolved.filter((r) => r.rarity.Key === key);
const mythique = byKey('mythique');
const legendary = byKey('legendaire');
const epic = byKey('epique');

let content = '';
let embeds = [];
if (mythique.length) {
  content = `\u{1F525} ${mention} vient de decrocher une carte MYTHIQUE !!!`;
  embeds = [{ color: hexToInt(mythique[0].rarity.ColorHex), title: '\u{1F525} ' + mythique.map((r) => r.card.Name).join(', '), description: `Rareté : **${mythique[0].rarity.Name}**`, image: imageOf(mythique[0].card) }];
} else if (legendary.length) {
  content = `\u{1F31F} ${mention} vient de decrocher une carte legendaire !`;
  embeds = [{ color: hexToInt(legendary[0].rarity.ColorHex), title: '\u{1F451} ' + legendary.map((r) => r.card.Name).join(', '), description: `Rareté : **${legendary[0].rarity.Name}**`, image: imageOf(legendary[0].card) }];
} else if (epic.length) {
  content = `\u2728 **${pseudo}** vient d'obtenir une carte epique.`;
  embeds = [{ color: hexToInt(epic[0].rarity.ColorHex), title: epic.map((r) => r.card.Name).join(', '), description: `Rareté : **${epic[0].rarity.Name}**`, image: imageOf(epic[0].card) }];
}

const shouldNotify = !!content && !!cfg.discordWebhookUrl && !cfg.discordWebhookUrl.startsWith('CHANGE-MOI');
return [{ json: { shouldNotify, webhookUrl: cfg.discordWebhookUrl, content, embeds, imageBase64: '' } }];

// Convertit le JPEG recu en base64 (canvas cote client, voir opening.js
// buildShareImage) en donnee binaire n8n, pour que le node HTTP Request
// natif (multipart-form-data) puisse l'attacher nativement - plus fiable
// qu'un multipart construit a la main, qui butait sur Discord ("Cannot
// send an empty message").
const item = $input.first().json;
const buffer = Buffer.from(item.imageBase64, 'base64');
const binary = await this.helpers.prepareBinaryData(buffer, 'share.jpg', 'image/jpeg');
return [{ json: item, binary: { share_jpg: binary } }];
